-- Venue Live Guest "Turnamen E-Sport". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara esport), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'esport', 'Turnamen E-Sport (arena neon)', 'esport', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 131, 'center 38%',
  $t${"name":"E-Sport","orn":"diamond","ui":{"ivory":"#F1EEFF","white":"#FFFFFF","soft":"#DDD5FF","soft2":"#A996F0","accent":"#7C3AED","deep":"#2B1A66","ink":"#1E1650","mute":"#6B5FA8","line":"#D3C9F7","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#F8F6FF","ink":"#1E1650","accent":"#7C3AED","gold":"#F5B700","leaf":"#DDD5FF","hbg":"rgba(241,238,255,.94)","hline":"#A996F0","motif":"diamond"},"hud":{"bg":"rgba(30,22,80,.9)","acc":"#5EE7FF","on":"#1E1650"},"scr":{"wine":"#2B1A66","veil":"241,238,255"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'esport');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/esport/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/esport/balloons.webp","w":1.3,"x":3.3,"z":-18,"mirror":true},"stall_snacks":{"url":"/assets/live-decor/esport/stall_snacks.webp","w":2.0},"stall_candy":{"url":"/assets/live-decor/esport/stall_candy.webp","w":1.4},"stall_drinks":{"url":"/assets/live-decor/esport/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/esport/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/esport/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/esport/arch.webp"},"fountain":{"url":"/assets/live-decor/esport/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/esport/sign.webp","w":1.5},"easel":{"url":"/assets/live-decor/esport/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/esport/table.webp"},"banner":{"url":"/assets/live-decor/esport/banner.webp","w":1.8},"gifts":{"url":"/assets/live-decor/esport/gifts.webp","w":1.8},"lamp":{"url":"/assets/live-decor/esport/lamp.webp","w":1.3,"x":3.3,"z":-12,"mirror":true},"rope":{"url":"/assets/live-decor/esport/rope.webp","w":1.3,"x":3.3,"z":-6,"mirror":true},"planter":{"url":"/assets/live-decor/esport/planter.webp","w":1.3,"x":3.3,"z":0,"mirror":true},"bush":{"url":"/assets/live-decor/esport/bush.webp","w":1.3,"x":3.3,"z":6,"mirror":true},"av_host":{"url":"/assets/live-decor/esport/av_host.webp","name":"Kapten Raven"},"av_l1":{"url":"/assets/live-decor/esport/av_l1.webp","name":"Kak Topi Kacamata"},"av_l2":{"url":"/assets/live-decor/esport/av_l2.webp","name":"Kak Ikat Kepala"},"av_l3":{"url":"/assets/live-decor/esport/av_l3.webp","name":"Kak Topi Bucket"},"av_p1":{"url":"/assets/live-decor/esport/av_p1.webp","name":"Kak Kuping Kucing"},"av_p2":{"url":"/assets/live-decor/esport/av_p2.webp","name":"Kak Hijab Hitam"},"av_p3":{"url":"/assets/live-decor/esport/av_p3.webp","name":"Kak Hijab Lilac"}}$d$::jsonb, background_url = '/assets/live-decor/esport/painting.webp', active = true, updated_at = now() where key = 'esport';
